import React, { useState, useEffect, useRef, useMemo, useCallback, useReducer, createContext, useContext, Component } from 'react';

function App() {
  const [count, setCount] = useState(0);

  const delayedAdd = () => {
    setTimeout(() => {
      setCount(count + 1);
    }, 200);
  };

  return (
    <div>
      <p id="count">Count: {count}</p>
      <button id="inc" onClick={() => setCount(count + 1)}>+</button>
      <button id="delayed" onClick={delayedAdd}>Delayed +</button>
    </div>
  );
}

export default App;

