import { describe, test, expect } from 'vitest';
import { render, fireEvent, waitFor } from '@testing-library/react';
import '@testing-library/jest-dom';
import React from 'react';
import App from '../src/App';

const tick = (ms = 20) => new Promise((resolve) => setTimeout(resolve, ms));

describe('The Lost Increment', () => {
  test('Renders count and both buttons', async () => {
    const { container: root } = render(<App />);
    if (!root.querySelector('#count')) throw new Error('No #count found');
if (!root.querySelector('#inc')) throw new Error('No #inc button found');
if (!root.querySelector('#delayed')) throw new Error('No #delayed button found');
  });

  test('Delayed + and immediate + both land', async () => {
    const { container: root } = render(<App />);
    root.querySelector('#delayed').click();
root.querySelector('#inc').click();
await tick();
await new Promise(r => setTimeout(r, 350));
const text = root.querySelector('#count').textContent;
const n = Number((text.match(/-?\d+/) || [NaN])[0]);
if (n !== 2)
  throw new Error('Expected count = 2 (1 from + and 1 from Delayed +), got ' + n);
  });

  test('Two delayed clicks both land', async () => {
    const { container: root } = render(<App />);
    // Current count is 2 from previous test (state persists across tests)
const before = Number((root.querySelector('#count').textContent.match(/-?\d+/) || [NaN])[0]);
root.querySelector('#delayed').click();
root.querySelector('#delayed').click();
await tick();
await new Promise(r => setTimeout(r, 400));
const after = Number((root.querySelector('#count').textContent.match(/-?\d+/) || [NaN])[0]);
if (after !== before + 2)
  throw new Error('Two Delayed + clicks should add 2, went from ' + before + ' to ' + after);
  });
});
